'use strict';
/*
 * Build the data a busy SPIM site would already hold, for local load tests.
 *
 *   node tools/seam-load-prepare.mjs <out.json>
 *
 * Everything here is generated by the real SEAM WASM engine: identities, signed
 * prekey bundles, and a genuine `SMW1` capsule from a completed X3DH handshake.
 * The load server seeds this into in-memory KV; no product logic is mocked.
 *
 * Safety: this script never opens a socket and never reads a URL. It only writes
 * a JSON file under the local filesystem.
 */

import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { randomBytes } from 'node:crypto';
import { signSession } from '../functions/api/_lib.js';

const require = createRequire(import.meta.url);
const WASM_DIR = process.env.SEAM_WASM_DIR || path.join(process.env.TMPDIR || '/tmp', 'seam-load-node');
const wasm = require(path.join(WASM_DIR, 'spim_wasm.js'));

const SECRET = process.env.SPIM_AUTH_SECRET || 'local-harness-secret';
const DAY = 86_400;

function envInt(name, fallback) {
  const n = Number(process.env[name]);
  return Number.isInteger(n) && n > 0 ? n : fallback;
}

const USERS = envInt('SEAM_LOAD_USERS', 700);
const PUBLISH_JOBS = envInt('SEAM_LOAD_PUBLISH_JOBS', 600);
const FETCH_BOXES = envInt('SEAM_LOAD_FETCH_BOXES', 48);
const FETCH_BUNDLES = envInt('SEAM_LOAD_FETCH_BUNDLES', 256);
const DRAIN_BOXES = envInt('SEAM_LOAD_DRAIN_BOXES', 400);
const ACK_BOXES = envInt('SEAM_LOAD_ACK_BOXES', 400);
const BOX_MESSAGES = envInt('SEAM_LOAD_BOX_MESSAGES', 8);

const out = process.argv[2];
if (!out) {
  console.error('usage: node tools/seam-load-prepare.mjs <out.json>');
  process.exit(2);
}

const now = Math.floor(Date.now() / 1000);
const expires = now + 30 * DAY;

function hex(bytes) {
  return randomBytes(bytes).toString('hex');
}

function mailbox() {
  return hex(16);
}

function bundleFrom(identity, at) {
  const generated = JSON.parse(wasm.seam_generate_prekeys(identity, 1, at, expires - at));
  return generated.bundles[0];
}

/* ---------------------------------------------------------------- users ---- */

const users = [];
for (let i = 0; i < USERS; i += 1) {
  const id = 'usr_load_' + String(i).padStart(6, '0');
  const email = `load${i}@example.test`;
  const { token } = await signSession({ id, email }, SECRET);
  users.push({ id, email, token });
}

/* ------------------------------------------------------- publish bundles ---- */

const publishJobs = [];
for (let i = 0; i < PUBLISH_JOBS; i += 1) {
  const user = users[i % users.length];
  const identity = new wasm.WasmIdentity();
  const bundles = [
    bundleFrom(identity, now),
    bundleFrom(identity, now),
  ];
  publishJobs.push({ mailbox: mailbox(), token: user.token, bundles });
}

/* --------------------------------------------------------- fetch bundles ---- */

// A real pool of signed bundles. The relay never verifies signatures, so a
// mailbox can be seeded with the same pool without changing server behaviour;
// the material is still genuine output from the engine.
const poolIdentity = new wasm.WasmIdentity();
const bundlePool = [];
for (let i = 0; i < FETCH_BUNDLES; i += 1) bundlePool.push(bundleFrom(poolIdentity, now));

const fetchMailboxes = [];
for (let i = 0; i < FETCH_BOXES; i += 1) {
  const user = users[i % users.length];
  fetchMailboxes.push({
    mailbox: mailbox(),
    owner: user.id,
    bundles: bundlePool.map((b) => JSON.parse(JSON.stringify(b))),
  });
}

/* ------------------------------------------------------- real capsule ------ */

const bob = new wasm.WasmIdentity();
const bobPrekeys = JSON.parse(wasm.seam_generate_prekeys(bob, 1, now, DAY));
const alice = new wasm.WasmIdentity();
const session = wasm.WasmSession.initiate(alice, JSON.stringify(bobPrekeys.bundles[0]), now);
const envelope = session.encrypt('load probe ' + hex(4), now);

// A second capsule for the legacy /capsules baseline endpoint.
const baselineBlob = randomBytes(1024).toString('base64');

/* -------------------------------------------------------- drain / ack ------ */

const drainMailboxes = [];
for (let i = 0; i < DRAIN_BOXES; i += 1) {
  const user = users[i % users.length];
  const box = mailbox();
  const messages = [];
  for (let m = 0; m < BOX_MESSAGES; m += 1) {
    messages.push({ id: hex(12), at: now - m, envelope });
  }
  drainMailboxes.push({ mailbox: box, owner: user.id, token: user.token, messages });
}

const ackMailboxes = [];
for (let i = 0; i < ACK_BOXES; i += 1) {
  const user = users[i % users.length];
  const box = mailbox();
  const messages = [];
  for (let m = 0; m < BOX_MESSAGES; m += 1) {
    messages.push({ id: hex(12), at: now - m, envelope });
  }
  ackMailboxes.push({ mailbox: box, owner: user.id, token: user.token, messages });
}

/* ----------------------------------------------------------------- write ---- */

const data = {
  version: 1,
  generated_at: now,
  auth_secret: SECRET,
  counts: {
    users: users.length,
    publish_jobs: publishJobs.length,
    fetch_boxes: fetchMailboxes.length,
    fetch_bundles_per_box: FETCH_BUNDLES,
    drain_boxes: drainMailboxes.length,
    ack_boxes: ackMailboxes.length,
    box_messages: BOX_MESSAGES,
  },
  envelope,
  baseline: { capsule_blob: baselineBlob },
  users: users.map(({ id, email, token }) => ({ id, email, token })),
  publishJobs,
  fetchMailboxes,
  drainMailboxes,
  ackMailboxes,
};

fs.mkdirSync(path.dirname(path.resolve(out)), { recursive: true });
fs.writeFileSync(out, JSON.stringify(data));
const bytes = fs.statSync(out).size;
console.log(`wrote ${out} (${(bytes / 1024 / 1024).toFixed(1)} MiB)`);
console.log(JSON.stringify(data.counts));
